// @vitest-environment happy-dom
/**
 * The repair-request document says whose numbers those are.
 *
 * The credit figures on this page are typed by the buyer or their agent, but the
 * page is generated by us and carries the inspection company's name, so a seller
 * or a contractor reading it has no way to tell the amounts apart from something
 * the inspector priced. One line of attribution fixes that, and every competitor
 * that ships a repair-request builder ships one.
 *
 * The load-bearing assertion is the SECOND one. The PDF is not a separate
 * renderer: `sharePdfRoute` calls Browser Rendering against this very URL with
 * `?print=1`, so anything the print stylesheet hides — `print:hidden`, which is
 * exactly what happened to the existing page footer — is absent from the
 * downloaded document while still looking correct in a browser. A disclosure
 * that lives only in the web view is the failure mode this test exists for.
 */
import { describe, it, expect } from "vitest";
import { render } from "@testing-library/react";
import { createRoutesStub } from "react-router";
import RepairRequestSharePage, {
  shareViewModel,
} from "./repair-request.$shareToken";

const ITEM = {
  sectionTitle: "Roof",
  itemLabel: "Shingles",
  commentSnapshot: "Several shingles are cracked.",
  // Non-empty on purpose: the attribution is about money on the page, so a
  // fixture with no money would not exercise the case it exists for.
  requestedCreditCents: 50000,
  note: null,
};

function renderShare() {
  const vm = shareViewModel({
    propertyAddress: "1 Main St",
    creditTotal: 50000,
    items: [ITEM],
  });
  const Stub = createRoutesStub([
    {
      path: "/repair-request/:shareToken",
      Component: RepairRequestSharePage,
      loader: () => ({ kind: "ok", vm }),
    },
  ]);
  return render(<Stub initialEntries={["/repair-request/tok"]} />);
}

describe("repair-request share page — amount attribution", () => {
  it("states that the amounts came from the client, not the inspection company", async () => {
    const { findByTestId } = renderShare();

    const el = await findByTestId("amount-attribution");
    const text = (el.textContent ?? "").replace(/\s+/g, " ");
    expect(text).toMatch(/entered by the client or their representative/i);
    expect(text).toMatch(/not provided, verified, or endorsed/i);
  });

  it("keeps the attribution in the printed/PDF render, not just on screen", async () => {
    const { findByTestId } = renderShare();

    const el = await findByTestId("amount-attribution");

    // The PDF is this page rendered through the print stylesheet. Any
    // `print:*` utility that removes the element (or its text) takes the
    // disclosure out of the file the seller actually receives.
    for (let node: HTMLElement | null = el; node; node = node.parentElement) {
      const cls = node.className;
      if (typeof cls !== "string") continue;
      expect(cls).not.toMatch(/(^|[\s:])print:hidden(\s|$)/);
      expect(cls).not.toMatch(/print:(?:opacity-0|invisible|sr-only)/);
    }
  });
});
